const W=1000,H=600, shopEl=document.getElementById('shop');
const species=[{name:'Pip',emoji:'🐤',value:8,color:'#ffd45a'},{name:'Bluebell',emoji:'🐦',value:12,color:'#61c8e5'},{name:'Puff',emoji:'🕊️',value:17,color:'#f7f0dc'},{name:'Rosie',emoji:'🐦',value:22,color:'#ff8b89'},{name:'Glimmer',emoji:'✨',value:40,color:'#c78aff'}];
const upgrades=[{id:'blaster',emoji:'🔫',name:'Pop-o-matic',desc:'A faster, snappier popper. Easier to catch the speedy ones.',base:45},{id:'lure',emoji:'🪇',name:'Fancy bird-call',desc:'Attract rare, extra-valuable sky-sprites more often.',base:65},{id:'satchel',emoji:'🧺',name:'Roomy satchel',desc:'Carry 4 more birds before heading to the shop.',base:55}];
let saved={};try{saved=JSON.parse(localStorage.getItem('feather-fortune-save')||'{}')||{}}catch{}
const state={cash:saved.cash||0,levels:{blaster:0,lure:0,satchel:0,...saved.levels},haul:saved.haul||[],birds:[],shots:[],puffs:[],mode:'hunt',aim:{x:650,y:240},playerX:155,last:0,spawn:0,shoot:0,reload:0,ammo:6,maxAmmo:6,keys:{},time:0,backgroundStars:Array.from({length:34},()=>({x:Math.random()*W,y:Math.random()*250,r:1+Math.random()*2,phase:Math.random()*8}))};
let toastTimer;
function save(){try{localStorage.setItem('feather-fortune-save',JSON.stringify({cash:state.cash,levels:state.levels,haul:state.haul}))}catch{}}
function ui(){document.getElementById('cash').textContent=state.cash;document.getElementById('haul').textContent=`${state.haul.length} / ${capacity()}`;const total=state.haul.reduce((n,b)=>n+b.value,0);document.getElementById('salevalue').textContent=`Your haul is worth 🪙${total}`;document.getElementById('sell').disabled=!state.haul.length;document.getElementById('goods').innerHTML=state.haul.length?state.haul.reduce((a,b)=>{a[b.name]=(a[b.name]||{count:0,emoji:b.emoji});a[b.name].count++;return a},{} )&&Object.entries(state.haul.reduce((a,b)=>(a[b.name]=(a[b.name]||{n:0,emoji:b.emoji}),a[b.name].n++,a),{})).map(([name,v])=>`<div class="item">${v.emoji} ${name} ×${v.n}</div>`).join(''):'<div class="item">Your satchel is empty — go catch some colorful sky-sprites!</div>';document.getElementById('upgrades').innerHTML=upgrades.map(u=>{const level=state.levels[u.id],cost=u.base*(level+1);return `<article class="upgrade"><div class="emoji">${u.emoji}</div><div><h3>${u.name} <small>Lv.${level}</small></h3><p>${u.desc}</p></div><button class="btn" data-up="${u.id}" ${state.cash<cost?'disabled':''}>🪙 ${cost}</button></article>`}).join('');}
function capacity(){return 8+state.levels.satchel*4}
function toast(msg){const e=document.getElementById('flash');e.textContent=msg;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),1350)}
function rounded(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function cloud(x,y,s=1){ctx.fillStyle='#fff9e9';ctx.beginPath();ctx.ellipse(x,y,47*s,19*s,0,0,Math.PI*2);ctx.ellipse(x-23*s,y-9*s,22*s,19*s,0,0,Math.PI*2);ctx.ellipse(x+8*s,y-18*s,25*s,27*s,0,0,Math.PI*2);ctx.ellipse(x+31*s,y-6*s,22*s,16*s,0,0,Math.PI*2);ctx.fill()}
function birdShape(x,y,s,color,wing,dir=1){ctx.save();ctx.translate(x,y);ctx.scale(dir*s,s);ctx.fillStyle=color;ctx.strokeStyle='#514354';ctx.lineWidth=2.4;ctx.lineJoin='round';ctx.beginPath();ctx.ellipse(0,0,23,16,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.beginPath();ctx.ellipse(-4,-10,11,7,wing,Math.PI,Math.PI*2);ctx.fillStyle=shade(color,-12);ctx.fill();ctx.stroke();ctx.fillStyle='#514354';ctx.beginPath();ctx.moveTo(-20,1);ctx.lineTo(-34,-5);ctx.lineTo(-27,8);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(20,-3);ctx.lineTo(32,1);ctx.lineTo(20,5);ctx.closePath();ctx.fillStyle='#f6a14b';ctx.fill();ctx.stroke();ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(10,-6,5.5,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#303444';ctx.beginPath();ctx.arc(12,-6,2.1,0,Math.PI*2);ctx.fill();ctx.restore()}
function shade(hex,amt){const n=parseInt(hex.slice(1),16),r=Math.max(0,Math.min(255,(n>>16)+amt)),g=Math.max(0,Math.min(255,((n>>8)&255)+amt)),b=Math.max(0,Math.min(255,(n&255)+amt));return `rgb(${r},${g},${b})`}
function drawHunt(){const t=state.time;const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#79d3e2');sky.addColorStop(.72,'#b8e9dc');sky.addColorStop(1,'#e8e8ae');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
state.backgroundStars.forEach(a=>{ctx.globalAlpha=.13+.12*Math.sin(t*2+a.phase);ctx.fillStyle='white';ctx.beginPath();ctx.arc(a.x,a.y,a.r,0,6.3);ctx.fill()});ctx.globalAlpha=1;
cloud(100+(t*11%1000),99,.8);cloud(560-(t*8%950),160,.62);cloud(860-(t*9%1100),69,.75);
ctx.fillStyle='#9bcf9b';ctx.beginPath();ctx.moveTo(0,360);ctx.quadraticCurveTo(180,240,350,345);ctx.quadraticCurveTo(530,250,740,347);ctx.quadraticCurveTo(865,280,1000,350);ctx.lineTo(1000,600);ctx.lineTo(0,600);ctx.fill();
ctx.fillStyle='#75b77f';ctx.beginPath();ctx.moveTo(0,414);ctx.quadraticCurveTo(220,320,420,430);ctx.quadraticCurveTo(680,330,1000,421);ctx.lineTo(1000,600);ctx.lineTo(0,600);ctx.fill();
ctx.fillStyle='#75c9d2';ctx.beginPath();ctx.moveTo(0,450);ctx.quadraticCurveTo(195,422,355,463);ctx.quadraticCurveTo(590,500,1000,441);ctx.lineTo(1000,600);ctx.lineTo(0,600);ctx.fill();ctx.fillStyle='#a1e2d9';for(let i=0;i<10;i++){let x=(i*138+t*18)%1060-30;ctx.beginPath();ctx.ellipse(x,511+Math.sin(i)*17,28,3,0,0,6.3);ctx.fill()}
// Mabel's shoppe on the far right
rounded(795,319,173,149,9,'#d98167');ctx.fillStyle='#f5cb6a';ctx.beginPath();ctx.moveTo(780,330);ctx.lineTo(880,253);ctx.lineTo(980,330);ctx.closePath();ctx.fill();ctx.strokeStyle='#514354';ctx.lineWidth=4;ctx.stroke();rounded(827,363,54,104,4,'#594963');rounded(895,350,56,45,4,'#b7e5df');ctx.strokeStyle='#fff3d4';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(923,351);ctx.lineTo(923,395);ctx.moveTo(895,373);ctx.lineTo(951,373);ctx.stroke();ctx.fillStyle='#514354';ctx.font='bold 14px Trebuchet MS';ctx.textAlign='center';ctx.fillText('MABEL’S',880,345);ctx.fillText('FEATHERS',880,362);
// daisies
for(let i=0;i<13;i++){let x=(i*83+21)%990,y=497+(i%3)*23;ctx.fillStyle='#467956';ctx.fillRect(x,y,2,24);ctx.fillStyle='#fff9e9';for(let k=0;k<5;k++){let a=k*1.256;ctx.beginPath();ctx.ellipse(x+Math.cos(a)*5,y+Math.sin(a)*5,3,5,a,0,6.3);ctx.fill()}ctx.fillStyle='#ffcb56';ctx.beginPath();ctx.arc(x,y,3,0,6.3);ctx.fill()}
// player and blaster
ctx.fillStyle='#34495c';ctx.beginPath();ctx.ellipse(state.playerX,477,37,9,0,0,6.3);ctx.fill();ctx.fillStyle='#f4bf9e';ctx.beginPath();ctx.arc(state.playerX,408,22,0,6.3);ctx.fill();ctx.fillStyle='#8c5c58';ctx.beginPath();ctx.arc(state.playerX-2,402,23,Math.PI,6.05);ctx.fill();rounded(state.playerX-25,428,50,45,12,'#ef8066');ctx.fillStyle='#ffe2a1';ctx.beginPath();ctx.arc(state.playerX+9,409,2,0,6.3);ctx.fill();
let dx=state.aim.x-state.playerX,dy=state.aim.y-449,angle=Math.atan2(dy,dx);ctx.save();ctx.translate(state.playerX+4,447);ctx.rotate(angle);rounded(0,-7,42,14,6,'#46546a');rounded(29,-10,13,20,5,'#ffc34c');ctx.restore();
// aim reticle
if(state.mode==='hunt'){ctx.strokeStyle='#fff8e9';ctx.lineWidth=2;ctx.setLineDash([4,5]);ctx.beginPath();ctx.arc(state.aim.x,state.aim.y,13,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.beginPath();ctx.moveTo(state.aim.x-19,state.aim.y);ctx.lineTo(state.aim.x-10,state.aim.y);ctx.moveTo(state.aim.x+10,state.aim.y);ctx.lineTo(state.aim.x+19,state.aim.y);ctx.moveTo(state.aim.x,state.aim.y-19);ctx.lineTo(state.aim.x,state.aim.y-10);ctx.moveTo(state.aim.x,state.aim.y+10);ctx.lineTo(state.aim.x,state.aim.y+19);ctx.stroke()}
// sign and ammo
rounded(19,18,235,42,14,'#fff8e9');ctx.fillStyle='#334155';ctx.font='900 16px Trebuchet MS';ctx.textAlign='left';ctx.fillText(state.mode==='hunt'?'BIRD BLITZ!  ✦  SKY MEADOW':'TURN RIGHT  →  MABEL’S',34,45);
rounded(819,18,158,42,14,'#fff8e9');ctx.fillStyle='#334155';ctx.textAlign='center';ctx.fillText(`POPS  ${state.ammo===0?'↻':state.ammo+' / '+state.maxAmmo}`,898,45);
}

