function render(){if(state.mode==='hunt'){drawHunt();for(const b of state.birds){ctx.save();ctx.translate(b.x,b.y);ctx.rotate(Math.sin(b.phase)*.05);birdShape(0,0,b.scale,species[b.species].color,b.wing,b.dir);ctx.restore()}for(const p of state.shots){ctx.fillStyle='#fff6bf';ctx.beginPath();ctx.arc(p.x,p.y,5,0,6.3);ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x-8,p.y);ctx.lineTo(p.x+8,p.y);ctx.stroke()}}else drawShop();for(const p of state.puffs){ctx.globalAlpha=p.life/p.max;ctx.fillStyle=p.color;for(let i=0;i<7;i++){let a=i*6.28/7;ctx.beginPath();ctx.arc(p.x+Math.cos(a)*(18+(1-p.life)*32),p.y+Math.sin(a)*(15+(1-p.life)*26),8*(p.life/p.max),0,6.3);ctx.fill()}ctx.globalAlpha=1}}
function openShop(){state.mode='shop';shopEl.classList.add('show');ui()}
function closeShop(){shopEl.classList.remove('show');state.mode='hunt'}
function pointer(e,fireNow=false){const r=canvas.getBoundingClientRect();state.aim.x=(e.clientX-r.left)*W/r.width;state.aim.y=(e.clientY-r.top)*H/r.height;if(fireNow)shoot()}
canvas.addEventListener('pointermove',e=>pointer(e));canvas.addEventListener('pointerdown',e=>{if(state.mode==='hunt'){pointer(e,true);canvas.focus?.()}});
document.getElementById('fire').addEventListener('pointerdown',e=>{e.preventDefault();shoot()});
document.getElementById('tradeBtn').addEventListener('click',openShop);document.getElementById('upgradeBtn').addEventListener('click',()=>{ui();shopEl.classList.add('show')});document.querySelector('[data-close]').addEventListener('click',closeShop);
document.getElementById('sell').addEventListener('click',()=>{if(!state.haul.length)return;const value=state.haul.reduce((n,b)=>n+b.value,0);state.cash+=value;state.haul=[];save();ui();toast(`Lovely! Mabel paid you ${value} coins!`);document.getElementById('shopline').textContent='Mabel is delighted with your latest delivery!'});
document.getElementById('upgrades').addEventListener('click',e=>{const btn=e.target.closest('[data-up]');if(!btn)return;const u=upgrades.find(a=>a.id===btn.dataset.up),cost=u.base*(state.levels[u.id]+1);if(state.cash<cost)return;state.cash-=cost;state.levels[u.id]++;save();ui();toast(`${u.name} upgraded!`)});
window.addEventListener('keydown',e=>{if(['Space','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='KeyE'){if(state.mode==='shop')closeShop();else openShop();return}if(e.code==='Escape'&&shopEl.classList.contains('show')){closeShop();return}if(e.code==='Space'){state.keys.Space=true;shoot()}if(e.code==='ArrowLeft')state.keys.ArrowLeft=true;if(e.code==='ArrowRight')state.keys.ArrowRight=true;if(e.key.toLowerCase()==='a')state.keys.a=true;if(e.key.toLowerCase()==='d')state.keys.d=true});
window.addEventListener('keyup',e=>{if(e.code==='Space')state.keys.Space=false;if(e.code==='ArrowLeft')state.keys.ArrowLeft=false;if(e.code==='ArrowRight')state.keys.ArrowRight=false;if(e.key.toLowerCase()==='a')state.keys.a=false;if(e.key.toLowerCase()==='d')state.keys.d=false});
window.addEventListener('blur',()=>state.keys={});
function frame(now){const dt=Math.min(.05,(now-state.last)/1000||0);state.last=now;update(dt);render();requestAnimationFrame(frame)}ui();requestAnimationFrame(frame);
})();

