 function toast(msg){const e=document.getElementById('flash');e.textContent=msg;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),1350)}
 function rounded(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
 function cloud(x,y,s=1){ctx.fillStyle='#fff9e9';ctx.beginPath();ctx.ellipse(x,y,47*s,19*s,0,0,Math.PI*2);ctx.ellipse(x-23*s,y-9*s,22*s,19*s,0,0,Math.PI*2);ctx.ellipse(x+8*s,y-18*s,25*s,27*s,0,0,Math.PI*2);ctx.ellipse(x+31*s,y-6*s,22*s,16*s,0,0,Math.PI*2);ctx.fill()}
